"""Generator biased towards non-trivial cores (self avoiding walks)."""
import random
from gen import canon, pathlinks, peel, find_order

def self_avoiding_walk(rng, adj, nodes, maxlen):
    start=rng.choice(nodes); p=[start]
    while len(p)<maxlen:
        cands=[x for x in adj[p[-1]] if x not in p]
        if not cands: break
        p.append(rng.choice(cands))
    return p

def build(rng, nnodes=None, maxwalk=None, nrec=None):
    n = nnodes or rng.randint(4,10)
    nodes=list(range(1,n+1))
    style=rng.choice(['cycle','tree','grid','random'])
    edges=set()
    if style=='cycle' and n>=3:
        perm=nodes[:]; rng.shuffle(perm)
        for i in range(n): edges.add(canon(perm[i],perm[(i+1)%n]))
    elif style=='grid':
        gw=rng.randint(2,3); gh=rng.randint(2,3)
        nodes=[]; 
        for r in range(gh):
            for c in range(gw): nodes.append(r*100+c+1)
        for r in range(gh):
            for c in range(gw):
                if c+1<gw: edges.add(canon(r*100+c+1, r*100+c+2))
                if r+1<gh: edges.add(canon(r*100+c+1, (r+1)*100+c+1))
        n=len(nodes)
    else:
        order=nodes[:]; rng.shuffle(order)
        for i in range(1,n):
            edges.add(canon(order[i], order[rng.randrange(i)]))
    extra = rng.randint(0, max(1,n//2))
    for _ in range(extra):
        a,b=rng.sample(nodes,2); edges.add(canon(a,b))
    edges=sorted(edges)
    adj={x:[] for x in nodes}
    for a,b in edges: adj[a].append(b); adj[b].append(a)
    return nodes, edges, adj

def gen(rng, maxcore=8, bigcore=False):
    nodes, edges, adj = build(rng)
    ixps=list(dict.fromkeys([rng.randint(900,905) for _ in range(rng.randint(0,2))]))
    ixpset=set(ixps)
    maxwalk = rng.randint(4,8)
    nrec = rng.randint(4,25)
    rib=[]
    for _ in range(nrec):
        p=self_avoiding_walk(rng, adj, nodes, maxwalk)
        q=[]
        for x in p:
            if ixps and rng.random()<0.12: q.append(rng.choice(ixps))
            if rng.random()<0.12: q.append(x)
            q.append(x)
        if len(q)>64: q=q[:64]
        rib.append({'path':q,'count':rng.choice([1,1,2,3,4,7,25,1000,1000000])})
    if rng.random()<0.15:
        rib.append({'path':[], 'count':1})
    if rng.random()<0.15:
        rib.append({'path':[rng.choice(nodes)], 'count':2})
    if rng.random()<0.2:
        a=rng.choice(nodes); rib.append({'path':[a, rng.choice(adj[a]), a], 'count':3})
    def norm(p):
        out=[]
        for a in p:
            if a in ixpset: continue
            if out and out[-1]==a: continue
            out.append(a)
        return out
    agg={}
    for rec in rib:
        q=norm(rec['path'])
        if len(q)<2 or len(set(q))!=len(q): continue
        agg[tuple(q)]=agg.get(tuple(q),0)+rec['count']
    links=set()
    for q in agg: links.update(pathlinks(q))
    rnd,cur=peel(agg)
    core=sorted(links-set(rnd))
    lim = 9 if not bigcore else 12
    if len(core)>lim: return None
    order=find_order(core,cur)
    if order is None: return None
    priors=[]; used=set()
    pool=sorted(set(edges)|links)
    for _ in range(rng.randint(0,5)):
        if not pool: break
        e=rng.choice(pool)
        if e in used: continue
        used.add(e)
        ee=(e[1],e[0]) if rng.random()<0.5 else e
        w=[rng.randint(0,1000000) for _ in range(3)]
        if sum(w)==0: w[rng.randrange(3)]=rng.randint(1,10)
        priors.append({'link':list(ee),'weights':w})
    declared=[]; usedd=set()
    for _ in range(rng.randint(0,4)):
        if not pool: break
        e=rng.choice(pool)
        if e in usedd: continue
        usedd.add(e)
        ee=(e[1],e[0]) if rng.random()<0.5 else e
        declared.append({'link':list(ee),'rel':rng.choice(['c2p','p2p','p2c'])})
    queries=[]
    for i in range(rng.randint(0,8)):
        r=rng.random()
        if r<0.6:
            p=self_avoiding_walk(rng, adj, nodes, rng.randint(1,8))
        elif r<0.75:
            p=[rng.randint(1,1000) for _ in range(rng.randint(0,6))]
        elif r<0.9:
            p=self_avoiding_walk(rng, adj, nodes, rng.randint(3,6))
            if len(p)>1: p=p[:1]+[p[-1]]+p[1:]
        else:
            p=[]
        if rng.random()<0.15 and ixps: p=list(p)+[rng.choice(ixps)]
        if rng.random()<0.2 and len(p)>2: p=p[::-1]
        a=rng.randint(0,1000000); b=rng.randint(a,1000000)
        if rng.random()<0.3: a,b=rng.randint(0,5),rng.randint(0,5)
        if b<a: a,b=b,a
        queries.append({'id':'q%d'%i,'path':list(p)[:64],'threshold':[a,b]})
    return {'version':1,'ixps':ixps,'rib':rib,'priors':priors,'declared':declared,'order':order,'queries':queries}
